// Probes the gh-1990 dialect with an HTTP 200 whose body is NOT JSON
// (captive portal / proxy error page): the legacy contract says every
// failure answers an empty info, never a throw.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart' as http_testing;
import 'package:test/test.dart';

void main() {
  http.Client clientOf(String body) => http_testing.MockClient(
    (request) async {
      if (request.url.host == 'api.github.com') {
        return http.Response(
          '{"token":"tk-exchanged","expires_at":9999999999}',
          200,
        );
      }
      return http.Response(body, 200);
    },
  );

  test('report API: malformed 200 body names a diagnostic, never throws', () async {
    final report = await fetchModelsForEndpointReport(
      'https://api.githubcopilot.com',
      apiKey: 'gho_ok',
      provider: 'copilot',
      client: clientOf('<html>captive portal</html>'),
    );
    expect(report.info.$1, isEmpty);
    expect(report.diagnostic, isNotNull);
  });

  test('legacy API: malformed 200 body answers empty, never throws', () async {
    final info = await fetchModelsForEndpoint(
      'https://api.githubcopilot.com',
      apiKey: 'gho_ok',
      provider: 'copilot',
      client: clientOf('not-json-at-all'),
    );
    expect(info.$1, isEmpty);
  });
}

